head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > parseDate]<br/>날짜 형식의 문자열을 지정된 포맷에 따라 파싱하여 JavaScript Date 객체로 변환합니다.",
    "validation" : [
        "날짜 형식의 문자열을 지정된 포맷에 따라 파싱하여 JavaScript Date 객체로 반환해야 합니다.",
        "str(필수) 파라미터로 파싱할 날짜 문자열을 설정할 수 있어야 합니다.",
        "str 파라미터의 비숫자 문자는 자동으로 제거되어야 합니다.",
        "format(선택) 파라미터로 날짜 형식 포맷을 설정할 수 있어야 합니다.",
        "format 파라미터를 생략하면 기본값 'yyyyMMdd' 로 동작해야 합니다.",
        "format 의 포맷 문자는 y(년), M(월), d(일), H(시), m(분), s(초) 를 지원해야 합니다.",
        "입력 문자열(비숫자 제거 후)의 길이와 format 의 길이가 일치하지 않으면 null 을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 로딩 시 선택된 시나리오에 해당하는 str / format 값 설정
    var initScenario = par_scenario.getValue();
    scwin.applyScenario(initScenario);
};



// 시나리오별 유효한 str / format 조합 (par_str, par_format input 에 자동 반영)
// format 이 "" 인 경우 format 파라미터 생략 시나리오
scwin.scenarioMap = {
    "1" : { "str" : "20230101",          "format" : "yyyyMMdd" },
    "2" : { "str" : "01222023112430",    "format" : "MMddyyyyHHmmss" },
    "3" : { "str" : "2023-01-01",        "format" : "yyyyMMdd" },
    "4" : { "str" : "20230101",          "format" : "" },
    "5" : { "str" : "2023010",           "format" : "yyyyMMdd" },
    "6" : { "str" : "20230715143045",    "format" : "yyyyMMddHHmmss" }
};

scwin.applyScenario = function (val) {
    if (Object.prototype.hasOwnProperty.call(scwin.scenarioMap, val)) {
        par_str.setValue(scwin.scenarioMap[val].str);
        par_format.setValue(scwin.scenarioMap[val].format);
    }
};

scwin.par_scenario_onviewchange = function (e) {
    scwin.applyScenario(par_scenario.getValue());
};



scwin.btn_parseDate_onclick = function () {
    var scenario = par_scenario.getValue();
    var str = par_str.getValue();
    var format = par_format.getValue();
    var ret = (scenario === "4") ? $p.parseDate(str) : $p.parseDate(str, format);

    if (ret === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : null");
    } else if (ret instanceof Date && !isNaN(ret.getTime())) {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : " + ret.toString());
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : (유효하지 않음) " + ret);
    }
}
